import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadUserData();
    loadSessions();
  }, []);

  const loadUserData = () => {
    const userData = localStorage.getItem('currentUser');
    if (userData) {
      setUser(JSON.parse(userData));
    }
  };

  const loadSessions = async () => {
    try {
      const token = localStorage.getItem('authToken');

      if (!token) {
        console.log('No token found');
        setLoading(false);
        return;
      }

      const response = await fetch('http://localhost:8000/api/sessions', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        console.log('✅ Sessions loaded:', data);
        setSessions(data);
      } else {
        console.error('❌ Failed to load sessions:', response.status);
      }
    } catch (error) {
      console.error('❌ Error loading sessions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/auth');
  };

  const handleStartSession = (tutorId, subject) => {
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    console.log('🚀 Starting NEW session with tutorId:', tutorId, 'subject:', subject);

    navigate(`/video/${roomId}`, {
      state: {
        tutorId: tutorId,
        subject: subject,
        resuming: false
      }
    });
  };

  const handleResumeSession = (session) => {
    navigate(`/video/${session.session_id}`, {
      state: {
        tutorId: session.tutor_id,  // ✅ Pass tutorId directly
        subject: session.subject,
        resuming: true
      }
    });
  };

  const tutors = [
    {
      id: 'omkar_ai',  // ✅ CORRECT ID
      name: 'Omkar',
      subject: 'AI & ML',
      description: 'Expert in Artificial Intelligence and Machine Learning',
      icon: '🧑‍💻'
    },
    {
      id: 'priya_biology',  // ✅ FIXED: Changed from 'priya_bio' to 'priya_biology'
      name: 'Priya',
      subject: 'Biology',
      description: 'Passionate Biology tutor specializing in life sciences',
      icon: '👩‍🔬'
    }
  ];

  // Calculate total messages
  const totalMessages = sessions.reduce((sum, session) => sum + session.message_count, 0);

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900">
      {/* Header */}
      <div className="bg-black/30 backdrop-blur-md border-b border-white/10">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold text-white">Saarthi</h1>
          <button
            onClick={handleLogout}
            className="px-4 py-2 bg-red-500/20 hover:bg-red-500/30 text-red-300 rounded-lg transition-all"
          >
            Logout
          </button>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 py-8">
        {/* Welcome Section */}
        <div className="mb-8">
          <h2 className="text-3xl font-bold text-white mb-2">
            Welcome back,
          </h2>
          <p className="text-2xl text-blue-200">
            {user?.name || 'Student'}
          </p>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
            <div className="text-4xl mb-2">📚</div>
            <div className="text-3xl font-bold text-white mb-1">
              {sessions.length}
            </div>
            <div className="text-gray-300 text-sm">Total Sessions</div>
          </div>

          <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
            <div className="text-4xl mb-2">💬</div>
            <div className="text-3xl font-bold text-white mb-1">
              {totalMessages}
            </div>
            <div className="text-gray-300 text-sm">Messages Sent</div>
          </div>

          <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
            <div className="text-4xl mb-2">🎯</div>
            <div className="text-3xl font-bold text-white mb-1">
              {tutors.length}
            </div>
            <div className="text-gray-300 text-sm">AI Tutors</div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Sessions List */}
          <div className="lg:col-span-2">
            <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
              <h3 className="text-xl font-semibold text-white mb-4">
                Your Learning Sessions
              </h3>

              {loading ? (
                <div className="text-center py-8">
                  <div className="text-gray-300">Loading sessions...</div>
                </div>
              ) : sessions.length === 0 ? (
                <div className="text-center py-8">
                  <div className="text-6xl mb-4">📝</div>
                  <p className="text-gray-300 mb-2">No sessions yet</p>
                  <p className="text-gray-400 text-sm">
                    Start your first learning session with an AI tutor!
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {sessions.map((session) => (
                    <div
                      key={session.id}
                      onClick={() => handleResumeSession(session)}
                      className="bg-white/5 hover:bg-white/10 rounded-lg p-4 border border-white/10 cursor-pointer transition-all group"
                    >
                      <div className="flex justify-between items-start mb-2">
                        <div>
                          <h4 className="font-semibold text-white group-hover:text-blue-300 transition-colors">
                            {session.subject}
                          </h4>
                          <p className="text-sm text-gray-400">
                            with {session.tutor_id === 'omkar_ai' ? 'Omkar' : 'Priya'}
                          </p>
                        </div>
                        <div className="text-xs text-gray-400">
                          {new Date(session.last_active).toLocaleDateString()}
                        </div>
                      </div>
                      <div className="flex items-center gap-4 text-xs text-gray-400">
                        <span>💬 {session.message_count} messages</span>
                        <span>📅 {new Date(session.created_at).toLocaleDateString()}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Tutors */}
            <div className="bg-white/10 backdrop-blur-sm rounded-xl p-6 border border-white/20">
              <h3 className="text-xl font-semibold text-white mb-4">
                Select a Tutor
              </h3>
              <div className="space-y-3">
                {tutors.map((tutor) => (
                  <div
                    key={tutor.id}
                    className="bg-white/5 rounded-lg p-4 border border-white/10"
                  >
                    <div className="flex items-start gap-3 mb-3">
                      <div className="text-3xl">{tutor.icon}</div>
                      <div className="flex-1">
                        <h4 className="font-semibold text-white">{tutor.name}</h4>
                        <p className="text-sm text-blue-300">{tutor.subject}</p>
                      </div>
                    </div>
                    <p className="text-xs text-gray-400 mb-3">
                      {tutor.description}
                    </p>
                    <button
                      onClick={() => handleStartSession(tutor.id, tutor.subject)}
                      className="w-full py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-lg transition-all text-sm font-medium"
                    >
                      Start New Session
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {/* Quick Actions */}
            <div className="bg-white/5 backdrop-blur-sm rounded-xl p-4 border border-white/10">
              <h3 className="font-semibold mb-3 text-sm text-gray-300">Quick Actions</h3>
              <div className="space-y-2 text-sm">
                <button 
                  onClick={() => alert('Analytics feature coming soon!')}
                  className="w-full text-left px-3 py-2 hover:bg-white/10 rounded-lg transition-all text-gray-300"
                >
                  📊 View Analytics
                </button>
                <button 
                  onClick={() => alert('Settings feature coming soon!')}
                  className="w-full text-left px-3 py-2 hover:bg-white/10 rounded-lg transition-all text-gray-300"
                >
                  ⚙️ Settings
                </button>
                <button 
                  onClick={() => alert('Feedback feature coming soon!')}
                  className="w-full text-left px-3 py-2 hover:bg-white/10 rounded-lg transition-all text-gray-300"
                >
                  💡 Give Feedback
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
